(() => {
const D=window.JOURNEY_DATA, root=document.getElementById('app');
const state={theme:localStorage.getItem('journey-theme')||'workbench',mode:localStorage.getItem('journey-mode')||'auto',language:localStorage.getItem('journey-language')||'zh',focus:new URLSearchParams(location.search).get('focus')||'model',scale:.82,panX:0,panY:0,route:location.pathname,showThemes:false,showPalette:false,layer:'structure',rev:new URLSearchParams(location.search).get('rev')==='00'?'00':'01',replaying:false};
if(!D.themes.some(t=>t.id===state.theme))state.theme='workbench';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const node=id=>D.nodes.find(n=>n.id===id), theme=()=>D.themes.find(t=>t.id===state.theme);
const nativeLight=new Set(['minimal','brutalist','swiss']);
const effectiveMode=()=>state.mode==='auto'?(nativeLight.has(state.theme)?'light':'dark'):state.mode;
function localizeDOM(scope){if(state.language!=='en')return;const dict=window.JOURNEY_I18N||{};const pairs=Object.entries(dict).sort((a,b)=>b[0].length-a[0].length);const translate=value=>{const lead=value.match(/^\s*/)[0],trail=value.match(/\s*$/)[0],key=value.trim();if(!/[\u3400-\u9fff]/.test(key))return value;let result=dict[key];if(!result){result=key;for(const [zh,en] of pairs)if(result.includes(zh))result=result.split(zh).join(en);result=result.replaceAll('，',', ').replaceAll('。','.').replaceAll('：',': ').replaceAll('；','; ').replaceAll('（',' (').replaceAll('）',')');}return lead+result+trail};const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);let current;while(current=walker.nextNode()){if(['SCRIPT','STYLE'].includes(current.parentElement?.tagName)||current.parentElement?.closest('.language-button'))continue;current.nodeValue=translate(current.nodeValue)}scope.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>{for(const attr of ['aria-label','placeholder','title'])if(el.hasAttribute(attr))el.setAttribute(attr,translate(el.getAttribute(attr)))})}
function toggleMode(){state.mode=effectiveMode()==='dark'?'light':'dark';localStorage.setItem('journey-mode',state.mode);render()}
function toggleLanguage(){state.language=state.language==='zh'?'en':'zh';localStorage.setItem('journey-language',state.language);render()}
function routeName(){let p=state.route.replace(/\/$/,'');if(p.startsWith('/modules/'))return 'module';if(p.startsWith('/stage/'))return 'stage';return p.slice(1)||'home'}
function href(path){return path==='home'?'/':`/${path}/`}
function setTheme(id){if(!D.themes.some(t=>t.id===id))return;state.theme=id;localStorage.setItem('journey-theme',id);state.showThemes=false;render()}
function navigate(path){history.pushState({},'',href(path)+(state.focus?'?focus='+encodeURIComponent(state.focus):''));state.route=location.pathname;state.showPalette=false;state.showThemes=false;render();window.scrollTo({top:0,behavior:'instant'})}
function setFocus(id,update=true){if(!node(id))return;if(['tool_call','tool_gate','read','edit','bash'].includes(id))state.rev='01';state.focus=id;if(update){let url=new URL(location.href);url.searchParams.set('focus',id);history.replaceState({},'',url)};document.querySelectorAll('[data-node]').forEach(e=>{e.classList.toggle('selected',e.dataset.node===id);e.classList.toggle('related',(state.rev==='01'?D.toolEdges:D.edges).some(l=>(l.source===id&&l.target===e.dataset.node)||(l.target===id&&l.source===e.dataset.node)))});renderInspector();if(state.theme==='kinetic'){document.querySelector('.graph-viewport')?.style.setProperty('--focus-shift',`${(node(id).x-350)*-.045}px`)}}
function themeButton(){return `<button class="theme-trigger" data-action="themes" aria-haspopup="dialog"><span class="theme-swatch" style="--swatch:${theme().color}"></span><span>${theme().name}</span><span class="chevron">⌄</span></button>`}
function header(){return `<header class="topbar"><a class="mark" href="/" data-link="home"><span class="mark-symbol">◈</span><span>AGENT<span class="mark-muted"> / </span>ARCHITECTURE</span></a><div class="top-state"><span class="state-mark">01</span><span>工具机制</span><span class="top-divider"></span><span>学习记录 · 未运行</span></div><nav class="topnav" aria-label="主要导航"><a href="/journey/" data-link="journey">演进历程</a><a href="/architecture/" data-link="architecture">架构画布</a><a href="/about/" data-link="about">关于</a></nav><div class="top-actions"><button class="cmd-button" data-action="palette" aria-label="打开命令面板">⌘ K</button><button class="setting-button" data-action="mode" aria-label="${effectiveMode()==='dark'?'切换浅色模式':'切换深色模式'}" title="${effectiveMode()==='dark'?'切换浅色模式':'切换深色模式'}">${effectiveMode()==='dark'?'☼':'☾'}</button><button class="setting-button language-button" data-action="language" aria-label="${state.language==='zh'?'Switch to English':'切换为中文'}" title="${state.language==='zh'?'Switch to English':'切换为中文'}">${state.language==='zh'?'EN':'中'}</button>${themeButton()}</div></header>`}
function stageNav(){return `<aside class="rail"><div class="rail-label">BUILD SEQUENCE <span>02 / ∞</span></div><button class="stage-item ${state.rev==='00'?'active':''}" data-action="rev00"><span class="stage-index">00</span><span><strong>Agent 的定义与最小循环</strong><small>知识整理 · 伪代码未运行</small></span><span class="stage-indicator">${state.rev==='00'?'◉':'○'}</span></button><button class="stage-item ${state.rev==='01'?'active':''}" data-action="rev01"><span class="stage-index">01</span><span><strong>模型的工具</strong><small>Read / Edit / Bash · 资料研究</small></span><span class="stage-indicator">${state.rev==='01'?'◉':'○'}</span></button><div class="rail-end"><span class="rail-heading">阅读路径</span><p>切换 00 与 01，比较工具从抽象节点到受控执行链的变化。</p><a href="/journey/" data-link="journey">查看阶段记录 <span>↗</span></a></div></aside>`}
function setRevision(rev){state.rev=rev;state.focus=rev==='00'?'model':'tool_gate';let url=new URL(location.href);url.searchParams.set('rev',rev);url.searchParams.set('focus',state.focus);history.replaceState({},'',url);render()}
function graph(){if(state.rev==='01')return graphTools();const edgePath={
  'input-model':['M238 151 H290',256,135],
  'model-result':['M508 151 H790',645,135],
  'model-tool':['M399 204 V331 H530',405,265],
  'tool-tool_result':['M748 331 H790',740,316],
  'tool_result-model':['M899 384 V422 H399 V204',600,411]
};let edges=D.edges.map(e=>{const [path,x,y]=edgePath[`${e.source}-${e.target}`];return `<g class="edge edge-${e.relation}" data-edge="${e.source}-${e.target}"><path d="${path}" marker-end="url(#arrow)"/><text x="${x}" y="${y}">${esc(e.label)}</text></g>`}).join('');let icons={input:'⌁',model:'◎',tool:'◇',tool_result:'↶',result:'↗'};let nodes=D.stages[0].nodes.map((id,i)=>{let n=node(id);return `<button class="graph-node ${n.id===state.focus?'selected':''}" data-node="${n.id}" style="--x:${n.x}px;--y:${n.y}px" aria-label="查看${n.title}模块"><span class="port port-left"></span><span class="node-top"><span class="node-icon">${icons[id]}</span><span class="node-type">${n.type}</span><span class="node-state">待实现</span></span><strong>${n.title}</strong><span class="node-role">${n.role}</span><span class="node-id">N.${String(i+1).padStart(2,'0')}</span><span class="port port-right"></span></button>`}).join('');return `<div class="graph-viewport" id="viewport" aria-label="最小 Agent 循环画布，可用按钮缩放，拖动画布平移"><div class="graph-world" id="world" style="transform:translate(${state.panX}px,${state.panY}px) scale(${state.scale})"><svg class="edges-svg" viewBox="0 0 1050 450" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 L9 5 L1 9"/></marker></defs>${edges}</svg>${nodes}</div><div class="viewport-coordinates">X 00.00 / Y 00.00<br>REVISION 00 — KNOWLEDGE</div></div>`}
function graphTools(){const points={model:[0,185],tool_call:[245,185],tool_gate:[490,185],read:[735,35],edit:[735,185],bash:[735,335],tool_result:[985,185]};const e=D.toolEdges.map(link=>{const [sx,sy]=points[link.source],[tx,ty]=points[link.target];let path,x,y;if(link.relation==='loop'){path=`M${sx+100} ${sy+104} V515 H110 V${ty+104}`;x=420;y=505}else{path=`M${sx+218} ${sy+52} C${sx+240} ${sy+52},${tx-22} ${ty+52},${tx} ${ty+52}`;x=(sx+218+tx)/2;y=(sy+ty)/2+42}return `<g class="edge edge-${link.relation}" data-edge="${link.source}-${link.target}"><path d="${path}" marker-end="url(#arrow)"/>${link.label?`<text x="${x}" y="${y}">${link.label}</text>`:''}</g>`}).join('');const icons={model:'◎',tool_call:'↗',tool_gate:'▣',read:'◧',edit:'✎',bash:'⌘',tool_result:'↶'};let nodes=D.stages[1].nodes.map((id,i)=>{const n=node(id),[x,y]=points[id];return `<button class="graph-node ${n.id===state.focus?'selected':''}" data-node="${n.id}" style="--x:${x}px;--y:${y}px" aria-label="查看${n.title}模块"><span class="port port-left"></span><span class="node-top"><span class="node-icon">${icons[id]}</span><span class="node-type">${n.type}</span><span class="node-state">资料研究</span></span><strong>${n.title}</strong><span class="node-role">${n.role}</span><span class="node-id">N.${String(i+1).padStart(2,'0')}</span><span class="port port-right"></span></button>`}).join('');return `<div class="graph-viewport tools-viewport" id="viewport" aria-label="工具机制画布，可用按钮缩放，拖动画布平移"><div class="graph-world tools-world" id="world" style="transform:translate(${state.panX}px,${state.panY}px) scale(${state.scale})"><svg class="edges-svg" viewBox="0 0 1230 560" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 L9 5 L1 9"/></marker></defs>${e}</svg>${nodes}</div><div class="viewport-coordinates">REVISION 01 — TOOL RESEARCH</div></div>`}
function canvas(){let newer=state.rev==='01';return `<main class="canvas-shell"><div class="canvas-heading"><div><span class="overline">ARCHITECTURE / REV ${state.rev}</span><h1>从零搭建 Agent<span class="title-dot">.</span></h1><p>${newer?'从最小循环走进 Tool：输入约束、执行权限与结果回灌。':'LLM 决定是否调用工具；工具结果返回上下文，再次进入模型。'}</p></div><div class="canvas-actions"><button data-action="reset">适应画布</button><button data-action="zoomout" aria-label="缩小">−</button><span id="zoom-level">${Math.round(state.scale*100)}%</span><button data-action="zoomin" aria-label="放大">＋</button></div></div><div class="revision-switch" role="group" aria-label="选择架构阶段"><button data-action="rev00" aria-pressed="${!newer}">00 · 最小循环</button><button data-action="rev01" aria-pressed="${newer}">01 · 工具机制</button></div><div class="canvas-frame"><div class="canvas-flags"><span>FIG. ${state.rev} / ${newer?'模型的工具':'Agent 的定义与最小循环'}</span><span class="flag-unverified">◇ ${newer?'学习研究 · 尚未运行':'知识整理 · 伪代码未运行'}</span></div>${graph()}${newer?`<div class="mobile-architecture" aria-label="工具架构文字概览"><div class="tool-mobile"><p>LLM → Tool Call → Schema / 校验 / Hook / Permission</p><div class="tool-mobile-cards">${D.toolStudy.cards.map(c=>`<button data-node="${c.id}"><small>${c.kind}</small><strong>${c.title}</strong><span>${c.question}</span></button>`).join('')}</div><p>Result / Error → Tool Result → LLM ↺</p></div></div>`:`<div class="mobile-architecture" aria-label="架构文字概览"><div class="mobile-flow"><button data-node="input"><small>01 / 输入</small><strong>User</strong><span>提出任务</span></button><span aria-hidden="true">↓</span><button data-node="model"><small>02 / 判断</small><strong>LLM</strong><span>需要工具吗？</span></button><div class="mobile-branches"><div><span>否 / NO TOOL</span><button data-node="result">Final Answer</button></div><div><span>是 / USE TOOL</span><button data-node="tool">Tool</button><span aria-hidden="true">↓</span><button data-node="tool_result">Tool Result<br><small>写回 messages → LLM ↺</small></button></div></div></div></div>`}<div class="canvas-footer"><div class="legend"><span><i class="legend-box"></i> ${newer?'研究节点':'概念节点'}</span><span><i class="legend-dash"></i> ${newer?'分支工具':'按需能力'}</span><span><i class="legend-line"></i> 关系 / 调用</span></div><span class="canvas-hint">滚轮缩放 · 拖动平移 · 点击节点查看详情</span></div></div><div class="canvas-bottom"><span>ARCHITECTURE IS A RECORD OF DECISIONS</span><div class="special-actions"><button class="replay-btn" data-action="replay">▶ 演示概念流</button><form class="terminal-form" id="terminal-form"><label for="terminal-input">$</label><input id="terminal-input" placeholder="focus read / stage 01" autocomplete="off" aria-label="输入页面命令"><button type="submit">↵</button></form><a href="/stage/${state.rev}/" data-link="stage/${state.rev}">阅读构建过程 <span>↗</span></a></div></div></main>`}
function inspectorHtml(){const n=node(state.focus)||node('tool_gate'),newer=state.rev==='01';return `<div class="inspector-inner"><div class="inspector-kicker">MODULE INSPECTOR <span>${state.rev} / ${newer?'07':'05'}</span></div><div class="inspector-hero"><span class="inspector-glyph">◈</span><h2>${n.title}</h2><span class="inspector-type">${n.type} / ${newer?'学习模型':'概念'}</span></div><div class="inspector-status"><span>◇ ${newer?'未运行验证':'未验证'}</span><span>STAGE ${state.rev}</span></div><div class="inspector-section"><small>WHAT / 它是什么</small><p>${n.role}。</p></div><div class="inspector-section"><small>WHY / 为什么需要</small><p>${n.why}</p></div><div class="io-grid"><div><small>输入</small><p>${n.inputs}</p></div><div><small>输出</small><p>${n.outputs}</p></div></div><div class="inspector-section"><small>CHANGE / 当前变化</small><p>${n.change}。</p></div><div class="inspector-section"><small>VERIFY / 如何验证</small><p>${n.verify}。</p></div><a class="inspector-link" href="/modules/${n.id}/" data-link="modules/${n.id}">阅读模块知识页 <span>↗</span></a></div>`}
function renderInspector(){let el=document.getElementById('inspector');if(el){el.innerHTML=inspectorHtml();localizeDOM(el)}}
function record(){const r=D.stages[0].record;return `<section class="record-band" id="record"><div class="record-intro"><span class="overline">BUILD LOG / 00</span><h2>Agent 的第一个知识点。</h2><p>从多种定义中提炼自己的理解，再用工具调用与反馈循环解释最小结构。伪代码尚未运行。</p><a href="/stage/00/" data-link="stage/00">阅读完整记录 ↗</a></div><div class="record-flow"><div><span>01 / QUESTION</span><strong>${r.problem}</strong></div><div><span>02 / MY UNDERSTANDING</span><strong>${D.insight}</strong></div><div><span>03 / LOOP</span><strong>${D.takeaway}</strong></div><div><span>04 / EVIDENCE</span><strong>${r.validation}</strong></div></div></section>`}
function home(){return `<div class="work-layout">${stageNav()}${canvas()}<aside class="inspector" id="inspector">${inspectorHtml()}</aside></div>${state.rev==='01'?toolRecord():record()}`}
function pageHeader(k,title,description){return `<div class="page-lede"><span class="overline">${k}</span><h1>${title}</h1><p>${description}</p></div>`}
function toolRecord(){const r=D.stages[1].record;return `<section class="record-band" id="record"><div class="record-intro"><span class="overline">BUILD LOG / 01</span><h2>Tool 不只是一个函数。</h2><p>一次人工搬运服务器命令结果的经历，引出对 Read、Edit、Bash 三类能力的研究。当前是资料整理，尚未运行 Agent。</p><a href="/stage/01/" data-link="stage/01">阅读第一阶段记录 ↗</a></div><div class="record-flow"><div><span>01 / START</span><strong>${D.toolStudy.reason}</strong></div><div><span>02 / INSIGHT</span><strong>${D.toolStudy.definition}</strong></div><div><span>03 / CHANGE</span><strong>${r.change}</strong></div><div><span>04 / EVIDENCE</span><strong>${r.validation}</strong></div></div></section>`}
function journey(){return `<div class="page-content">${pageHeader('JOURNEY / 00 → 01','一张图，持续演进','先建立 Agent 的最小循环，再逐层研究 Tool 的执行边界。')}<div class="timeline"><a class="timeline-entry" href="/stage/00/" data-link="stage/00"><span class="timeline-num">00</span><div><small>LEARNING / 伪代码未运行</small><h2>Agent 的定义与最小循环</h2><p>定义、个人理解和 LLM → Tool → Tool Result → LLM 的最小反馈循环。</p></div><span>↗</span></a><a class="timeline-entry current" href="/stage/01/" data-link="stage/01"><span class="timeline-num">01</span><div><small>RESEARCH / 尚未运行</small><h2>模型的工具</h2><p>从静态 IP 的亲身经历出发，研究 Read、Edit、Bash 的完整工具链及执行边界。</p></div><span>↗</span></a></div></div>`}
function architecture(){return `<div class="architecture-page">${pageHeader('ARCHITECTURE / REV '+state.rev,state.rev==='01'?'Tool 的执行边界':'最小 Agent Loop',state.rev==='01'?'切换 00 与 01，比对抽象 Tool 如何展开成受控执行链；这是研究图，不是运行中的系统。':'选择节点查看职责。画布展示知识模型，尚不是已运行的系统。')}<div class="architecture-layout">${canvas()}<aside class="inspector" id="inspector">${inspectorHtml()}</aside></div><div class="text-equivalent"><h2>架构的文字说明</h2>${state.rev==='01'?`<p>模型提出 Tool Call。工具运行框架校验请求、执行 Hook 和权限判断，再将请求交给 Read、Edit 或 Bash。工具输出或错误被整理为 Tool Result，返回模型以继续判断。</p><p>REV 01 展开的是上一版抽象 Tool 的内部机制，研究依据为作者提供的学习包；未提供自行实现与运行验证。</p>`:`<p>用户输入进入 LLM。模型若不需要工具，直接返回最终结果；若需要工具，执行 Tool、取得 Tool Result，并把结果作为 tool 消息追加到 messages，再调用 LLM。这个循环可以重复，直到模型不再发起工具调用。</p><p>这里的 messages 是当前运行中的上下文；跨会话持久化记忆与独立规划模块尚未加入。</p>`}</div></div>`}
function stage(){if(state.route.includes('/01'))return stageOne();let r=D.stages[0].record;let sections=[['01 / PROBLEM','为什么做',r.problem],['02 / INPUT','当时输入了什么',r.input],['03 / DISCUSSION','定义如何对照',r.discussion],['04 / DECISION','我的理解',r.decision],['05 / ARCHITECTURE CHANGE','最小循环如何运行',r.change],['06 / IMPLEMENTATION','当前产出',r.implementation],['07 / VALIDATION','怎样验证',r.validation],['08 / OPEN QUESTIONS','下一步的问题',r.open],['09 / WHAT I LEARNED','我学到了什么',r.learned]];return `<div class="page-content reading-page">${pageHeader('BUILD LOG / 00','Agent 的定义与最小循环','第一个知识点：把工具调用、反馈与再次推理连成一个可解释的循环。')}<div class="stage-note">◇ 状态：知识整理完成　/　伪代码未运行　/　第一阶段现已收录工具研究</div><div class="definition-block"><div class="section-label">01 / DEFINITIONS</div><h2>不同来源，四个侧重点</h2><p>以下是对官方资料的中文概括，并非逐字引文。</p><div class="definition-grid">${D.definitions.map(d=>`<a href="${d.url}" target="_blank" rel="noopener noreferrer"><small>${d.name} / ${d.label}</small><strong>${d.summary}</strong><span>查看官方资料 ↗</span></a>`).join('')}</div></div><div class="insight-block"><div class="section-label">02 / MY UNDERSTANDING</div><h2>我的理解</h2><blockquote>${D.insight}</blockquote><p>这是我的第一个 Agent 知识点。这里提到的规划和记忆，是我对完整系统的理解；下面的最小循环还没有独立的规划模块或跨会话持久化记忆。</p></div><div class="loop-explainer"><div class="section-label">03 / MINIMUM LOOP</div><h2>一次判断，两条分支</h2><div class="loop-steps"><div>① 调用 LLM</div><div>② 是否需要 Tool？</div><div>否 → 返回结果</div><div>是 → 执行 Tool → Tool Result → 写回上下文 → 再次调用 LLM ↺</div></div><p>${D.takeaway}</p></div><div class="code-block"><div><span class="section-label">04 / PSEUDOCODE</span><span>Python · 说明控制流，尚未运行</span></div><pre><code>${esc(D.code)}</code></pre><p>call_llm 与 run_tool 是抽象接口。错误处理、终止策略、最大迭代次数和持久化留待后续阶段实现。</p></div><div class="reading-grid"><div class="reading-index">${sections.map((s,i)=>`<a href="#section-${i}">${s[0]}</a>`).join('')}</div><article class="reading-body">${sections.map((s,i)=>`<section id="section-${i}"><small>${s[0]}</small><h2>${s[1]}</h2><p>${s[2]}</p></section>`).join('')}</article></div></div>`}
function stageOne(){let r=D.stages[1].record,study=D.toolStudy;let sections=[['01 / PROBLEM','从一次真实经历出发',r.problem],['02 / INPUT','研究输入',r.input],['03 / DISCUSSION','如何理解 Tool',r.discussion],['04 / DECISION','先研究三个基础工具',r.decision],['05 / ARCHITECTURE CHANGE','画布怎么变化',r.change],['06 / OUTPUT','本阶段产出',r.implementation],['07 / VALIDATION','证据与局限',r.validation],['08 / NEXT','下一步',r.open],['09 / LEARNED','我学到了什么',r.learned]];return `<div class="page-content reading-page stage-one">${pageHeader('BUILD LOG / 01','模型的工具','从人工执行命令并回传结果的经历，走向 Tool 的受控执行设计。')}<div class="stage-note">◇ 状态：资料研究完成　/　作者实现与运行尚未验证</div><div class="insight-block"><div class="section-label">01 / ORIGIN</div><h2>为什么需要工具？</h2><blockquote>${study.reason}</blockquote><p>问题是：能否让 LLM 自己执行操作、直接看到结果，再决定下一步？</p></div><div class="definition-block"><div class="section-label">02 / WHAT IS A TOOL</div><h2>${study.definition}</h2><p>作者提供的资料对 Anthropic、LangChain、OpenAI 与 Google ADK 的 Tool 定义做了中文概括。这里记录学习结论，不视作逐字引文或已验证的产品实现。</p></div><div class="loop-explainer"><div class="section-label">03 / EXECUTION PATH</div><h2>从一次 Tool Call 到再次判断</h2><ol class="tool-steps">${study.layers.map((item,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${item}</li>`).join('')}</ol><p>${study.boundary}</p></div><div class="section-label">04 / THREE CORE TOOLS</div><div class="tool-study-grid">${study.cards.map(card=>`<article class="tool-study-card"><small>${card.kind} / TOOL</small><h2>${card.title}</h2><p>${card.question}</p><ol>${card.steps.map(step=>`<li>${step}</li>`).join('')}</ol><p>${card.detail}</p><a href="/modules/${card.id}/" data-link="modules/${card.id}">打开 ${card.title} 知识页 ↗</a></article>`).join('')}</div><div class="loop-explainer"><div class="section-label">05 / TOOL MAP</div><h2>其他工具，留作地图</h2><p>${study.other}</p><p>工具存在、暴露给模型和允许执行，是三个不同的判断。</p></div><div class="reading-grid"><div class="reading-index">${sections.map((entry,i)=>`<a href="#stage1-${i}">${entry[0]}</a>`).join('')}</div><article class="reading-body">${sections.map((entry,i)=>`<section id="stage1-${i}"><small>${entry[0]}</small><h2>${entry[1]}</h2><p>${entry[2]}</p></section>`).join('')}</article></div><div class="study-source"><h2>资料与证据</h2><p>内容整理自作者提供的「stage1-agent-tools.zip」：总述、学习路线、Read／Edit／Bash 执行链、源码学习摘录和其他工具地图。本站只呈现作者的学习总结与重新组织的图解；运行证据待后续补充。</p><a href="/compare/" data-link="compare">查看 REV 00 → 01 的变化 ↗</a></div></div>`}
function modulePage(){let id=state.route.split('/')[2],n=node(id)||node('agent'),card=D.toolStudy.cards.find(c=>c.id===id);state.focus=n.id;if(card)state.rev='01';return `<div class="page-content reading-page">${pageHeader('MODULE / '+n.id.toUpperCase(),n.title,n.role)}<div class="stage-note">◇ ${card?'资料研究 · 作者运行尚未验证':'知识模型 · 代码未运行'}</div>${card?`<div class="insight-block"><div class="section-label">STAGE 01 / ${card.kind}</div><h2>${card.question}</h2><p>${card.detail}</p></div><div class="reading-grid"><div class="reading-index"><a href="/architecture/?rev=01&focus=${n.id}" data-link="architecture">← 返回架构图</a><a href="/stage/01/" data-link="stage/01">阅读完整阶段记录 ↗</a></div><article class="reading-body">${card.steps.map((step,i)=>`<section><small>${String(i+1).padStart(2,'0')} / EXECUTION</small><h2>${step}</h2></section>`).join('')}<section><small>EVIDENCE</small><h2>研究状态</h2><p>依据作者提供的学习包与执行链整理；尚未提供作者自行运行本工具的验证记录。</p></section></article></div>`:`<div class="reading-grid"><div class="reading-index"><a href="/architecture/?rev=${state.rev}&focus=${n.id}" data-link="architecture">← 返回架构图</a></div><article class="reading-body"><section><small>01 / WHAT</small><h2>职责</h2><p>${n.role}。</p></section><section><small>02 / WHY</small><h2>引入原因</h2><p>${n.why}</p></section><section><small>03 / CONTRACT</small><h2>输入与输出</h2><p>输入：${n.inputs}<br>输出：${n.outputs}</p></section><section><small>04 / EVIDENCE</small><h2>实现与验证</h2><p>${n.change}；${n.verify}。</p></section></article></div>`}</div>`}
function compare(){return `<div class="page-content">${pageHeader('COMPARE / 00 → 01','架构版本对比','第一阶段细化了 Tool 的内部机制；两版都是知识模型，均未证明 Agent 已运行。')}<div class="revision-comparison"><div><small>REV 00 / 最小循环</small><h2>抽象 Tool</h2><p>User → LLM → Tool → Tool Result → LLM；模型无需工具时直接返回。</p><a href="/architecture/?rev=00" data-link="architecture" data-rev="00">查看 REV 00 ↗</a></div><div><small>REV 01 / 工具机制</small><h2>展开执行链</h2><p>Tool Call → 输入约束 / Hook / 权限 → Read、Edit、Bash → Tool Result → LLM。</p><a href="/architecture/?rev=01" data-link="architecture" data-rev="01">查看 REV 01 ↗</a></div></div><div class="change-list"><h2>发生了什么变化</h2><p><strong>新增：</strong>Tool Call、执行边界和 Read／Edit／Bash 三类工具的职责。</p><p><strong>细化：</strong>原来的抽象 Tool 与 Tool Result 之间加入校验、执行和错误反馈。</p><p><strong>仍未验证：</strong>没有作者自行实现的工具代码或运行日志；不要将学习摘录当作已完成的系统。</p></div></div>`}
function about(){return `<div class="page-content reading-page">${pageHeader('ABOUT / PROJECT','从零搭建，逐步解释','一个公开源码的学习作品：让新手理解架构如何形成，也让决策与验证过程可回溯。')}<div class="about-grid"><div class="about-manifesto">一张架构图，<br><em>记录每一次判断。</em></div><div><h2>这个站点会记录什么</h2><p>每一阶段的起点、输入、讨论、作者判断、架构变化、实现方法、验证证据与尚未解决的问题。ChatGPT 的建议和作者的实际工作会清楚区分。</p><h2>更新原则</h2><p>按真实搭建顺序新增模块，不预设固定技术路线；未实现和未验证的内容保持明确标记。</p><a href="/goal.html">阅读目标文档 ↗</a></div></div></div>`}
function design(){return `<div class="page-content design-page">${pageHeader('DESIGN / 10 WORLDS','选择阅读这段旅程的方式','相同架构与记录，十种不同的画布、排版和交互语言。选择会保存在当前设备。')}<div class="theme-grid">${D.themes.map(t=>`<button class="theme-card preview-${t.id} ${state.theme===t.id?'chosen':''}" data-theme-choice="${t.id}" aria-pressed="${state.theme===t.id}"><span class="theme-card-head"><span>${t.number} / ${t.english.toUpperCase()}</span><span>${state.theme===t.id?'✓ 当前主题':'↗'}</span></span><span class="preview-graph"><i></i><i></i><i></i><b></b></span><strong>${t.name}</strong><span class="theme-mood">${t.mood}</span><span class="theme-signature">${t.signature}</span></button>`).join('')}</div><p class="design-footnote">设计规范来自本项目的十主题设计包。REV 00 与 REV 01 是学习画布；依赖可运行 Agent 的交互留待后续阶段。</p></div>`}
function overlays(){return `${state.showThemes?`<div class="overlay" data-action="closeoverlay"><div class="theme-dialog" role="dialog" aria-modal="true" aria-label="选择主题"><div class="dialog-head"><div><span class="overline">DESIGN SYSTEM</span><h2>切换视觉世界</h2></div><button data-action="closeoverlay" aria-label="关闭">×</button></div><div class="dialog-options">${D.themes.map(t=>`<button data-theme-choice="${t.id}" class="dialog-theme ${state.theme===t.id?'chosen':''}"><span class="dialog-dot" style="background:${t.color}"></span><span>${t.number} · ${t.name}</span><small>${t.english}</small>${state.theme===t.id?'✓':''}</button>`).join('')}</div><a href="/design/" data-link="design">查看十种风格的设计页 ↗</a></div></div>`:''}${state.showPalette?`<div class="overlay" data-action="closeoverlay"><div class="palette" role="dialog" aria-modal="true" aria-label="命令面板"><label for="command-search">搜索阶段、模块、页面或主题</label><input id="command-search" type="search" autocomplete="off" placeholder="例如 Agent、架构、极简…" aria-label="搜索命令"><div class="command-results" id="command-results"></div><div class="palette-foot">↑↓ 选择　Enter 打开　Esc 关闭</div></div></div>`:''}`}
function render(){document.documentElement.dataset.revision=state.rev;document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.mode=state.mode;document.documentElement.lang=state.language==='en'?'en':'zh-CN';const title=routeName()==='home'?'从零搭建 Agent':routeName()==='design'?'主题设计':'架构学习日志';document.title=(state.language==='en'?(window.JOURNEY_I18N[title]||title):title)+' · Architecture Journey';const view=({home,journey,architecture,stage,compare,about,design,module:modulePage})[routeName()]||home;root.innerHTML=header()+view()+`<footer class="site-footer"><span>AGENT ARCHITECTURE JOURNEY · REV 00 → 01</span><span>阶段 01 / 工具研究，尚未运行</span><a href="https://github.com/Adversit/dk_learn_agent" target="_blank" rel="noopener">GitHub ↗</a></footer>`+overlays();localizeDOM(root);if(state.language==='en')root.querySelectorAll('a[href="/goal.html"]').forEach(a=>a.href='/goal-en.html');if(state.showPalette){document.getElementById('command-search').focus();updateCommands('')}if(document.getElementById('world'))setupCanvas()}
const commands=[...D.nodes.map(n=>({label:n.title,meta:'模块',run:()=>{navigate('architecture');setFocus(n.id)}})),...['home','journey','architecture','compare','about','design'].map(p=>({label:({home:'首页',journey:'演进历程',architecture:'架构画布',compare:'版本对比',about:'关于',design:'主题选择'})[p],meta:'页面',run:()=>navigate(p)})),...D.themes.map(t=>({label:t.name,meta:'主题',run:()=>setTheme(t.id)}))];let commandIndex=0,filtered=[];
function updateCommands(q){filtered=commands.filter(c=>(c.label+c.meta+(window.JOURNEY_I18N[c.label]||'')+(window.JOURNEY_I18N[c.meta]||'')).toLowerCase().includes(q.toLowerCase()));commandIndex=0;let target=document.getElementById('command-results');if(target){target.innerHTML=filtered.map((c,i)=>`<button data-command="${i}" class="${i===0?'active':''}"><span>${esc(c.label)}</span><small>${c.meta}</small></button>`).join('')||'<p>没有匹配结果</p>';localizeDOM(target)}}
function setupCanvas(){let viewport=document.getElementById('viewport');if(!viewport)return;state.scale=Math.min(.82,Math.max(.5,(viewport.clientWidth-32)/(state.rev==='01'?1230:1050)));let moving=false,sx=0,sy=0;viewport.onpointerdown=e=>{if(e.target.closest('button'))return;moving=true;sx=e.clientX-state.panX;sy=e.clientY-state.panY;viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')};viewport.onpointermove=e=>{if(!moving)return;state.panX=e.clientX-sx;state.panY=e.clientY-sy;applyTransform()};viewport.onpointerup=()=>{moving=false;viewport.classList.remove('dragging')};viewport.onwheel=e=>{e.preventDefault();state.scale=Math.min(1.8,Math.max(.5,state.scale*(e.deltaY<0?1.09:.91)));applyTransform()};applyTransform()}
function applyTransform(){let w=document.getElementById('world');if(w)w.style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.scale})`;let z=document.getElementById('zoom-level');if(z)z.textContent=Math.round(state.scale*100)+'%'}
function replay(){if(state.replaying)return;state.replaying=true;document.querySelector('.graph-viewport')?.classList.add('replaying');setTimeout(()=>{state.replaying=false;document.querySelector('.graph-viewport')?.classList.remove('replaying')},4400)}
root.addEventListener('click',e=>{let t=e.target.closest('[data-theme-choice]');if(t){setTheme(t.dataset.themeChoice);return}t=e.target.closest('[data-command]');if(t){filtered[Number(t.dataset.command)]?.run();return}t=e.target.closest('[data-node]');if(t){setFocus(t.dataset.node);return}t=e.target.closest('[data-link]');if(t){e.preventDefault();if(t.dataset.rev)state.rev=t.dataset.rev;navigate(t.dataset.link);return}t=e.target.closest('[data-action]');if(!t)return;let a=t.dataset.action;if(a==='closeoverlay'&&e.target!==t&&t.classList.contains('overlay'))return;({themes:()=>{state.showThemes=true;render()},palette:()=>{state.showPalette=true;render()},mode:toggleMode,language:toggleLanguage,closeoverlay:()=>{state.showThemes=false;state.showPalette=false;render()},stage00:()=>navigate('stage/00'),rev00:()=>setRevision('00'),rev01:()=>setRevision('01'),reset:()=>{let v=document.getElementById('viewport');state.scale=v?Math.min(.82,Math.max(.5,(v.clientWidth-32)/(state.rev==='01'?1230:1050))):.82;state.panX=0;state.panY=0;applyTransform()},zoomin:()=>{state.scale=Math.min(1.8,state.scale+.15);applyTransform()},zoomout:()=>{state.scale=Math.max(.5,state.scale-.15);applyTransform()},replay})[a]?.()});
root.addEventListener('input',e=>{if(e.target.id==='command-search')updateCommands(e.target.value)});
root.addEventListener('submit',e=>{if(e.target.id!=='terminal-form')return;e.preventDefault();let q=document.getElementById('terminal-input').value.trim().toLowerCase(),[action,...args]=q.split(/\s+/);if(action==='focus'&&node(args[0]))setFocus(args[0]);else if(action==='stage'&&['00','01'].includes(args[0]))navigate('stage/'+args[0]);else if(action==='theme'&&D.themes.some(t=>t.id===args[0]))setTheme(args[0]);else if(action==='help')document.getElementById('terminal-input').placeholder='focus agent · stage 00 · theme minimal';else document.getElementById('terminal-input').placeholder='未知命令，输入 help 查看用法';if(document.getElementById('terminal-input'))document.getElementById('terminal-input').value=''});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.showPalette=!state.showPalette;render();return}if(e.key==='Escape'&&(state.showPalette||state.showThemes)){state.showPalette=false;state.showThemes=false;render();return}if(state.showPalette){if((e.key==='ArrowDown'||e.key==='ArrowUp')&&filtered.length){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+filtered.length)%filtered.length;document.querySelectorAll('[data-command]').forEach((b,i)=>b.classList.toggle('active',i===commandIndex))}if(e.key==='Enter'&&filtered.length){e.preventDefault();filtered[commandIndex].run()}}});
window.addEventListener('popstate',()=>{state.route=location.pathname;state.rev=new URLSearchParams(location.search).get('rev')==='00'?'00':'01';state.focus=new URLSearchParams(location.search).get('focus')||state.focus;render()});
render();
})();
